{% set company_doc = frappe.db.get_value("Company", doc.company, ["company_logo", "email", "phone_no"], as_dict=1) if doc.company else {} %}

{% set _addr_link = frappe.db.get_value("Dynamic Link", {"link_doctype": "Customer", "link_name": doc.name, "parenttype": "Address"}, "parent") %}
{% set _addr = frappe.db.get_value("Address", _addr_link, ["address_line1", "city", "state", "pincode"], as_dict=1) if _addr_link else {} %}
{% set _contact_link = frappe.db.get_value("Dynamic Link", {"link_doctype": "Customer", "link_name": doc.name, "parenttype": "Contact"}, "parent") %}
{% set _contact = frappe.db.get_value("Contact", _contact_link, ["first_name", "last_name", "phone", "mobile_no", "email_id"], as_dict=1) if _contact_link else {} %}

{# Get list of active factory assignments for this dealer #}
{% set factory_assignments = frappe.get_all("Factory Assignment",
    filters={"customer": doc.name, "active": 1},
    fields=["factory"],
    order_by="assignment_date asc"
) %}
{% set factories = [] %}
{% for fa in factory_assignments %}
  {% set fname = frappe.db.get_value("Supplier", fa.factory, "supplier_name") %}
  {% set floc = frappe.db.get_value("Supplier", fa.factory, ["city", "state"], as_dict=1) %}
  {% if fname %}
    {% set _ = factories.append(fname ~ " located in " ~ (floc.city or '') ~ ", " ~ (floc.state or '')) %}
  {% endif %}
{% endfor %}

{%- macro format_phone(phone) -%}
{%- if phone -%}
{%- set digits = phone | replace("+", "") | replace("-", "") | replace(" ", "") | replace("(", "") | replace(")", "") -%}
{%- if digits | length == 10 -%}
+1 ({{ digits[:3] }}) {{ digits[3:6] }}-{{ digits[6:] }}
{%- elif digits | length == 11 and digits[0] == '1' -%}
+1 ({{ digits[1:4] }}) {{ digits[4:7] }}-{{ digits[7:] }}
{%- else -%}
{{ phone }}
{%- endif -%}
{%- endif -%}
{%- endmacro -%}

<link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&display=swap" rel="stylesheet">

<style>
  .inv {
    font-family: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif !important;
    font-weight: 500 !important; color: #000 !important;
    font-size: 13px !important; line-height: 1.2 !important; width: 100% !important;
  }
  .inv table { border-collapse: collapse !important; width: 100% !important; }
  .inv td, .inv th { padding: 0 !important; vertical-align: top !important; }
  .inv-div {
    border-top: 1px solid #ddd !important; border-bottom: none !important;
    border-left: none !important; border-right: none !important;
    height: 0 !important; margin: 32px 0 !important; background: none !important;
  }
  .lbl { font-weight: 600 !important; font-size: 13px !important; color: #000 !important; padding-bottom: 6px !important; }
  .val { font-size: 13px !important; font-weight: 500 !important; color: #333b44 !important; line-height: 1.4 !important; }
  .inv-items {
    width: 100% !important; border-collapse: separate !important; border-spacing: 0 !important;
    border-radius: 4px !important; overflow: hidden !important;
  }
  .inv-items thead th {
    background: #000 !important; color: #fff !important; font-weight: 600 !important;
    font-size: 12px !important; padding: 12px 20px !important; text-align: left !important;
    letter-spacing: 0.3px !important; border: none !important;
  }
  .inv-items thead tr th:first-child { border-top-left-radius: 4px !important; }
  .inv-items thead tr th:last-child { border-top-right-radius: 4px !important; }
  @media print { .inv-items thead { display: table-row-group !important; } }
  .inv-items tbody td {
    padding: 12px 20px !important; font-size: 12px !important; font-weight: 500 !important;
    color: #333b44 !important; border-bottom: 1px solid #e0e0e0 !important;
    vertical-align: top !important; background: #f5f5f5 !important;
  }
  .inv-items tbody td.f-lbl { font-weight: 700 !important; color: #000 !important; width: 260px !important; }
  .inv-items tbody td.f-val { font-weight: 500 !important; color: #000 !important; }
  .inv-items tbody tr:last-child td { border-bottom: none !important; }
  .inv-items tbody tr:last-child td:first-child { border-bottom-left-radius: 4px !important; }
  .inv-items tbody tr:last-child td:last-child { border-bottom-right-radius: 4px !important; }
  .legal-text { font-size: 11px !important; line-height: 1.6 !important; color: #333b44 !important; }
  .legal-text p { margin: 0 0 10px 0 !important; }
  .section-head { font-size: 13px !important; font-weight: 700 !important; color: #000 !important; padding: 16px 0 8px 0 !important; }
  .sig-line {
    border-bottom: 1px solid #333 !important; min-width: 280px !important;
    display: inline-block !important; margin-left: 8px !important;
  }
  .no-break { page-break-inside: avoid !important; }
  .factory-list { font-weight: 700 !important; font-size: 12px !important; color: #000 !important; line-height: 1.6 !important; }
</style>

<div class="inv">

  <!-- ═══ HEADER ═══ -->
  <table>
    <tr>
      <td style="width: 50% !important;">
        <img src="/files/dcr-logo.png" style="height: 40px !important; object-fit: contain !important; display: block !important;" alt="Dealer Capital Resources">
      </td>
      <td style="width: 50% !important; text-align: right !important;">
        <div style="font-size: 11px !important; color: #333b44 !important;">2111 Palomar Airport Rd #270</div>
        <div style="font-size: 11px !important; color: #333b44 !important;">Carlsbad, CA 92011</div>
        <div style="font-size: 11px !important; color: #333b44 !important;">(800) 454-1116</div>
      </td>
    </tr>
  </table>

  <div class="inv-div"></div>

  <!-- ═══ TITLE ═══ -->
  <div style="font-size: 20px !important; font-weight: 600 !important; color: #000 !important; padding-bottom: 4px !important;">Retailer Agreement</div>
  <div class="val" style="color: #c00 !important; font-weight: 600 !important;">{{ doc.customer_name }}</div>
  <div class="val" style="color: #c00 !important; font-weight: 600 !important;">{{ doc.dealer_license_no or '' }}</div>

  <!-- ═══ INTRO ═══ -->
  <div class="legal-text" style="padding-top: 16px !important;">
    <p>This Retailer Agreement ("<strong>Agreement</strong>") is made by and between Dealer Capital Resources, Inc. ("<strong>DCR</strong>") and <span style="text-decoration: underline !important; color: #c00 !important;">{{ doc.customer_name }}</span> (the "<strong>Retailer</strong>") for the purpose of outlining how the parties will do business together.</p>

    <p>The effective date of this Agreement is <span style="text-decoration: underline !important; color: #c00 !important;">{{ frappe.utils.formatdate(frappe.utils.today(), "MMMM d, yyyy") }}</span> and this Agreement will be in effect until either party cancels per the cancellation terms outlined in this agreement.</p>
  </div>

  <!-- ═══ MANUFACTURERS ═══ -->
  <div class="section-head">Manufacturers</div>
  <div class="legal-text">
    <p>DCR has agreements with multiple manufactured and modular home builders and manufacturers. DCR's agreements allow the Retailer to purchase homes directly from these manufacturers at factory invoice. Homes available to DCR are subject to change and can be beyond DCR's control. The Retailer agrees to adhere to each manufacturer's specific requirements and understands that DCR does not control the manufacturer's specific requirements.</p>

    <p>As an independent retailer, the Retailer is free to discuss pricing, specifications, service and all other day-to-day business activities directly with the manufacturer's representatives. However, Retailer understands all homes ordered by Retailer will require a purchase order issued by DCR to the manufacturer prior to construction of any home. Manufacturers under this arrangement which the Retailer may be authorized to purchase from under this program include:</p>
  </div>

  <!-- Factory list from Factory Assignments -->
  <div class="factory-list" style="padding: 8px 0 8px 0 !important;">
    {% if factories %}
      {% for f in factories %}
      <div>{{ f }}</div>
      {% endfor %}
    {% else %}
    <div style="color: #999 !important; font-weight: 500 !important;">No factory assignments yet — assign factories to this dealer to populate this list.</div>
    {% endif %}
  </div>

  <div class="legal-text">
    <p>These manufacturers may change at any time and without notice by DCR.</p>
  </div>

  <!-- ═══ LICENSING ═══ -->
  <div class="section-head">Licensing</div>
  <div class="legal-text">
    <p>It is the Retailer's responsibility, at their sole cost, to obtain and keep current all licenses required by applicable state, federal and/or local law (as may be required) to sell new manufactured and modular homes in their geographic area. Further, the Retailer agrees to follow all local, state and federal laws pertaining to the sale of any homes purchased from any manufacturer under this Agreement.</p>
  </div>

  <!-- ═══ FINANCING OF HOMES ═══ -->
  <div class="section-head">Financing of Homes</div>
  <div class="legal-text">
    <p>The Retailer may decide to enter into a separate written master financing or flooring agreement with DCR or other lenders or investors. Any agreement made between the Retailer and another investor or lender is separate from this agreement and is between the lender or investor and the Retailer only.</p>
  </div>

  <!-- ═══ MANUFACTURER REBATES ═══ -->
  <div class="section-head">Manufacturer Rebates</div>
  <div class="legal-text">
    <p>The Retailer understands and agrees that manufacturer rebates earned through this program, if any, are hereby assigned to DCR and authorizes the manufacturer to pay such rebate to DCR or its affiliates as may be directed by DCR. The Retailer understands this assignment will remain in place throughout this Agreement. DCR has agreed to pay the following rebates to the Retailer:</p>

    <p style="color: #c00 !important; font-weight: 600 !important;">{{ doc.rebate_percentage or '{ }' }}% of each home's qualifying amount once paid in full.</p>

    <p>Any amounts owed to Retailer, can be used to offset past due amounts owed to DCR under this agreement or a separate master inventory financing or flooring agreement. Rebates are calculated using qualifying amounts and purchases as defined by each manufacturer.</p>
  </div>

  <!-- ═══ RETAIL TRANSACTIONS ═══ -->
  <div class="section-head">Retail Transactions</div>
  <div class="legal-text">
    <p>The Retailer acknowledges that DCR is not a party to its retail transactions with the end-user customers (i.e. purchasers of the homes). Retailer hereby agrees to indemnify, defend and hold harmless DCR and its affiliates, officers, directors, shareholders, members, employees, agents and representatives and their respective successors and assigns (the "Indemnified Person"), from and against any and all suits, actions, proceedings, claims, damages, losses, fines, penalties, charges, liabilities and expenses (including reasonable attorneys' fees and disbursements) relating to or arising out of Retailer's standard business including the purchase, set-up, installation, sale, assignment or transfer of a home to any third party, or any other agreement entered into by Retailer relating to such a transaction.</p>
  </div>

  <!-- ═══ WARRANTY AND SERVICE ═══ -->
  <div class="section-head">Warranty and Service</div>
  <div class="legal-text">
    <p>There are no warranties expressed or implied between the Retailer and DCR. Each manufacturer will offer its standard warranty and DCR shall not be liable or responsible in any way for a manufacturer's warranty or performance thereon. The Retailer must install the home to each manufacturer's specific installation requirements, obtain all required permits, approvals and authorizations relating to the movement, installation and set-up of a home, and use licensed contractors to fulfill any work or warranty service. All warranty service must be handled per each manufacturer's and local jurisdiction's protocol. Service is to be handled between the manufacturer and the Retailer.</p>
  </div>

  <!-- ═══ CANCELLATION ═══ -->
  <div class="section-head">Cancellation</div>
  <div class="legal-text">
    <p>Retailer may cancel this Agreement with written notice after all homes subject to the terms of this Agreement have been sold to third parties by Retailer and closed escrow. Cancellation must be in writing. Any homes ordered with a purchase order issued prior to cancellation are subject to terms of this Agreement. DCR may cancel this agreement without notice.</p>

    <p>This Agreement may be validly executed and delivered by fax or other electronic transmission which signatures shall be deemed and treated as originals. This Agreement may be executed in one or more counterpart signature pages and when taken together treated as a whole, original agreement. This Agreement is governed by California Law, regardless of choice of law provisions. This agreement contains the complete understanding of the Retailer and DCR. No representations, inducements, promises, agreements, arrangements or undertakings, whether oral or written, express or implied, between the Retailer and DCR not herein embodied shall have any force or effect. DCR has the right to modify the terms of this Agreement with prior written notice to Retailer, which modification shall take effect fifteen (15) days after such notice provided that Retailer has not otherwise provided notice to cancel this Agreement.</p>
  </div>

  <div class="inv-div"></div>

  <!-- ═══ SIGNATURES ═══ -->
  <div class="no-break">
    <table style="width: 100% !important;">
      <tr>
        <td style="width: 48% !important; vertical-align: top !important; padding-right: 4% !important;">
          <table class="inv-items">
            <thead>
              <tr><th>"DCR"</th></tr>
            </thead>
            <tbody>
              <tr><td class="f-val">Dealer Capital Resources, Inc.<br>a California corporation</td></tr>
              <tr><td class="f-val" style="padding-top: 20px !important;">By: <span style="border-bottom: 1px solid #333 !important; display: inline-block !important; min-width: 180px !important;">&nbsp;</span></td></tr>
              <tr><td class="f-val">Robert Mazzola</td></tr>
              <tr><td class="f-val">2111 Palomar Airport Rd #270<br>Carlsbad, CA 92011</td></tr>
              <tr><td class="f-val" style="padding-top: 12px !important;">Date: <span style="border-bottom: 1px solid #333 !important; display: inline-block !important; min-width: 150px !important;">&nbsp;</span></td></tr>
            </tbody>
          </table>
        </td>
        <td style="width: 48% !important; vertical-align: top !important;">
          <table class="inv-items">
            <thead>
              <tr><th>"RETAILER"</th></tr>
            </thead>
            <tbody>
              <tr><td class="f-val">{{ doc.customer_name }}</td></tr>
              <tr><td class="f-val" style="padding-top: 20px !important;">By: <span style="border-bottom: 1px solid #333 !important; display: inline-block !important; min-width: 180px !important;">&nbsp;</span></td></tr>
              <tr><td class="f-val">{{ ((_contact.first_name or '') ~ ' ' ~ (_contact.last_name or '')) | trim }}</td></tr>
              <tr><td class="f-val">{{ _addr.address_line1 or '' }}<br>{{ (_addr.city or '') ~ ', ' ~ (_addr.state or '') ~ ' ' ~ (_addr.pincode or '') }}</td></tr>
              <tr><td class="f-val" style="padding-top: 12px !important;">Date: <span style="border-bottom: 1px solid #333 !important; display: inline-block !important; min-width: 150px !important;">&nbsp;</span></td></tr>
            </tbody>
          </table>
        </td>
      </tr>
    </table>
  </div>

  <div class="inv-div"></div>

  <!-- ═══ FOOTER ═══ -->
  <table>
    <tr>
      <td style="width: 50% !important; vertical-align: top !important;">
        <img src="/files/dcr-icon.png" style="height: 25px !important; object-fit: contain !important; display: block !important; filter: brightness(0) !important;" alt="DCR">
      </td>
      <td style="width: 50% !important; text-align: right !important; vertical-align: top !important;">
        <div style="font-size: 10px !important; color: #999 !important;">2111 Palomar Airport Rd #270 – Carlsbad – California – 92011 &nbsp; (800)454-1116 main &nbsp; (760)279-9464 fax</div>
      </td>
    </tr>
  </table>

</div>
